import re

def transform_to_hagrid(sentence):
    outside_quotes = re.sub(r'".*?"', '', sentence)

    if "Hagrid" not in outside_quotes:
        return sentence

    exact_replacements = {
        'you': 'yeh', 'You': 'Yeh',
        'to': 'ter', 'To': 'Ter',
        'and': "an'", 'And': "An'",
        'me': 'meh', 'Me': 'Meh'
    }

    def apply_rules(match):
        word = match.group(0)

        if word in exact_replacements:
            return exact_replacements[word]

        if word.lower().startswith('h'):
            word = "'" + word[1:]

        if len(word) > 0 and word[-1].lower() in ['f', 't', 'd', 'g']:
            word = word[:-1] + "'"

        return word

    def process_quotes(match):
        content = match.group(1)
        transformed_content = re.sub(r'[a-zA-Z]+', apply_rules, content)
        return f'"{transformed_content}"'

    return re.sub(r'"(.*?)"', process_quotes, sentence)

num = int(input())
for i in range(num):
    lines = input()
    print(transform_to_hagrid(lines))

